import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"13、【同人】 離下乾上","description":"溫公易說 - 13、【同人】 離下乾上","frontmatter":{"title":"13、【同人】 離下乾上","description":"溫公易說 - 13、【同人】 離下乾上"},"headers":[],"relativePath":"classics/wengong/014.md","filePath":"classics/wengong/014.md"}'),l={name:"classics/wengong/014.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_13、【同人】-離下乾上" tabindex="-1">13、【同人】 離下乾上 <a class="header-anchor" href="#_13、【同人】-離下乾上" aria-label="Permalink to “13、【同人】 離下乾上”">​</a></h1><h3 id="彖曰-同人-柔得位得中而應乎幹-曰同人。同人曰同人於野-亨利涉大川-幹行也。文明以健-中正而應-君子正也。惟君子為能通天下之志。" tabindex="-1">彖曰：同人，柔得位得中而應乎幹，曰同人。同人曰同人於野，亨利涉大川，幹行也。文明以健，中正而應，君子正也。惟君子為能通天下之志。 <a class="header-anchor" href="#彖曰-同人-柔得位得中而應乎幹-曰同人。同人曰同人於野-亨利涉大川-幹行也。文明以健-中正而應-君子正也。惟君子為能通天下之志。" aria-label="Permalink to “彖曰：同人，柔得位得中而應乎幹，曰同人。同人曰同人於野，亨利涉大川，幹行也。文明以健，中正而應，君子正也。惟君子為能通天下之志。”">​</a></h3><p>同人者，何？同於人之謂也。君子樂與人同，小人樂與人異。與人同者，人亦同之；與人異者，人亦異之。同則相愛，異則相惡。愛則相利，惡則相害。相利則交安，相害則交危。利害安危之端，在於同人，不可不察也。何謂君子樂與人同？請借魯事以言之。夫季孟異室而皆出於桓，魯衛異國而皆出於姬，姬姜異姓而皆為中國，夷夏異俗而皆列於此。君子之樂與人同也，是以近者悅，遠者來。同人之利，豈不大哉！何謂小人樂與人異？小人曰：季孟異室也，吾何與哉？又曰：彼此異民也，吾何與哉？又曰：爾汝異身也，吾何與哉？此樂與人異也，是以民有災而君弗恤，父有疾而子弗憂，兄有禍而弟弗救也。異之為害，豈不大哉！《詩》曰：自西自東，自南自北，無思不服，同之至也。又曰：翕翕訿訿，亦孔之哀。又曰：噂背憎職，競由人異之至也。然則同而已矣，其曰同人者，何？同之道極於人也，草木禽獸不可同也。同人於野，亨利涉大川，利君子貞，何也？曰：野則言其遠也，君子同其遠，小人同其近。遠故無不同也，近故迭相攻也。迭相攻非同人之道也。然則聖人其有私乎？曰：有。聖人之私，大眾人之私。小聖人者，以天下為私者也。藝谷樹蔬而食之，犕牛乘馬而畜使之，皆所以役物而養人也。所私不亦大乎？夫惟聖人為能愛其身，愛其身故愛其親，愛其親故愛其國，愛其國故愛其道。道者，所以保天下而兼利之也。未有危人之親而人不危其親者也，害人之身而人不害其身者也。天下交害之而身不亡者，未之有也。然則危人適所以自危，害人適所以自害也。烏在其能私哉？夫君子小人，其為愛身一也。君子之愛身也遠，小人之愛身也近。遠故大，近故小。小者非他也，智不及也是。故識其大者為大人，識其小者為小人。非其志之異也，識之蔽也。君子同於正，故其同大；小人同於邪，故其同小。邪正者，小大之分也。何謂君子能通天下之志？天下之志莫不欲利而惡害，欲安而惡危，欲治而惡亂。君子能安之利之治之，使天下猶一人也。此之謂能通天下之志。</p><h3 id="象曰-天與火同人-君子以類族辨物。" tabindex="-1">象曰：天與火同人，君子以類族辨物。 <a class="header-anchor" href="#象曰-天與火同人-君子以類族辨物。" aria-label="Permalink to “象曰：天與火同人，君子以類族辨物。”">​</a></h3><h3 id="初九-同人於門-無咎-象曰-出門同人-又誰咎也。" tabindex="-1">初九：同人於門，無咎 象曰：出門同人，又誰咎也。 <a class="header-anchor" href="#初九-同人於門-無咎-象曰-出門同人-又誰咎也。" aria-label="Permalink to “初九：同人於門，無咎 象曰：出門同人，又誰咎也。”">​</a></h3><p>初者，動之始也。夫向於左者必背於右，附於前者必離於後。故同者必有所異也。初九出門同人，無咎，言未有系也。</p><h3 id="六二-同人於宗-吝-象曰-同人於宗-吝道也。" tabindex="-1">六二：同人於宗，吝 象曰：同人於宗，吝道也。 <a class="header-anchor" href="#六二-同人於宗-吝-象曰-同人於宗-吝道也。" aria-label="Permalink to “六二：同人於宗，吝 象曰：同人於宗，吝道也。”">​</a></h3><p>宗類也。類之中又有類焉。同其類者，所同狹也，故吝。</p><h3 id="九三-伏戎於莽-升其高陵-三歲不興-象曰-伏戎於莽-敵剛也。三歲不興-安行也。" tabindex="-1">九三：伏戎於莽，升其高陵，三歲不興 象曰：伏戎於莽，敵剛也。三歲不興，安行也。 <a class="header-anchor" href="#九三-伏戎於莽-升其高陵-三歲不興-象曰-伏戎於莽-敵剛也。三歲不興-安行也。" aria-label="Permalink to “九三：伏戎於莽，升其高陵，三歲不興 象曰：伏戎於莽，敵剛也。三歲不興，安行也。”">​</a></h3><h3 id="九四-乘其墉-弗克攻-吉-象曰-乘其墉-義弗克也。其吉-則困而反則也。" tabindex="-1">九四：乘其墉，弗克攻，吉 象曰：乘其墉，義弗克也。其吉，則困而反則也。 <a class="header-anchor" href="#九四-乘其墉-弗克攻-吉-象曰-乘其墉-義弗克也。其吉-則困而反則也。" aria-label="Permalink to “九四：乘其墉，弗克攻，吉 象曰：乘其墉，義弗克也。其吉，則困而反則也。”">​</a></h3><p>九三伏戎於莽，九四：乘其墉，弗克攻，吉。何也？三四者，上下之際，同異之分也。故迭爭而交不勝也。伏戎於莽者，下襲上；乘其墉者，上陵下。上可變，下不可變，逆順之勢也。</p><h3 id="九五-同人先號咷而後笑-大師克相遇-象曰-同人之先-以中直也。大師相遇-言相剋也。" tabindex="-1">九五：同人先號咷而後笑，大師克相遇 象曰：同人之先，以中直也。大師相遇，言相剋也。 <a class="header-anchor" href="#九五-同人先號咷而後笑-大師克相遇-象曰-同人之先-以中直也。大師相遇-言相剋也。" aria-label="Permalink to “九五：同人先號咷而後笑，大師克相遇 象曰：同人之先，以中直也。大師相遇，言相剋也。”">​</a></h3><p>九五君也，以中正而施同人者也。夫君子好同，小人好異，德之未充，信之未孚。近者不服，遠者不懷，故號咷也。中則不阿，正則不私。不阿不私，天下歸之。始於憂勤，終於逸樂，故後笑也。同者之與多，異者之與寡。寡不足以勝眾，故聖人在上，天下大同者，化於眾也。子曰：君子之道，或出或處，或默或語，跡之異也。二人同心，其利斷金。言道之同也。二人言其寡也，金物之難斷者也。二人同心，猶可以斷，況於眾乎？同心之言，其臭如蘭。蘭，芬物也。言猶如是，況其道乎？美之至也。</p><h3 id="上九-同人於郊-無悔-象曰-同人於郊-志未得也。" tabindex="-1">上九：同人於郊，無悔 象曰：同人於郊，志未得也。 <a class="header-anchor" href="#上九-同人於郊-無悔-象曰-同人於郊-志未得也。" aria-label="Permalink to “上九：同人於郊，無悔 象曰：同人於郊，志未得也。”">​</a></h3><p>郊者，外也。不同於人而亦不異於人，是以無悔，而志未得也。</p><p>附</p><p>按序卦之義，否者物不相交之卦也。不相交則異，異則爭，爭則窮，故受之以同人。同人者，所以通之也。物通則大有矣。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
